// @name Transit departures (London, UK)
// @background #0f172a
// @refresh 60
// The next arrivals at one or two stops in London, as a station board: the
// Underground, the Elizabeth line, the DLR, the Overground lines, trams and
// buses, each line in its color, where it goes and the minutes until it
// comes. Live predictions from Transport for London's own API (no key
// needed). The last good ones are kept on disk (the private `board` field),
// and an error says what went wrong.
import { due, loadBoard, stopOf } from './board'
import { refreshStops } from './json'
import { tfl } from './tfl'
import { drawBoard, setupCard } from './ui'

const TITLE = 'Transit departures'

export function get(app: FrameOSApp, context: FrameOSContext) {
  const stops = [stopOf(app.state.stop), stopOf(app.state.stop2)].filter((stop) => stop.query)
  if (!stops.length) {
    return setupCard(app, context, TITLE, "Add a stop in the scene settings: its TfL StopPoint id, from the address of its page on tfl.gov.uk (940GZZLUKSX is King's Cross St. Pancras).")
  }
  const queries = stops.map((stop) => stop.query)
  const key = queries.join('/')
  const now = Date.now()
  let board = loadBoard(app, key)
  if (due(board, now)) board = refreshStops(key, board, now, queries, (query) => tfl(query, now))
  return drawBoard(app, context, { provider: 'TfL', title: TITLE, labels: stops.map((stop) => stop.label), queries, board })
}

