// The departures a station board has, and what it shows of them: which
// ones, the time as minutes or a clock, a delay, and a line's color as each
// panel can show it.

export type Departure = {
  line: string
  color: string
  text: string
  to: string
  at: number
  live: boolean
  delay: number | null
  gone: boolean
  where: string
}

export type Stop = { name: string; list: Departure[] }

// The last good departures, kept in the scene's private `board` field (on
// disk), and what happened since: `at` when they came, `tried` when the last
// request went out, `error` what went wrong with it.
export type Board = {
  key: string
  at: number
  tried: number
  stops: Stop[]
  error: string
  feedTime?: number
  names?: Record<string, { id: string; name: string }>
}

export const MINUTE = 60 * 1000

// Not asked again sooner than this, whatever renders the scene (a tap, a
// window coming forward): the refresh interval sets the pace.
export const FETCH_GAP = 25 * 1000

// A stop as it is typed: "70075, 70076", or with a name of your own before
// an equals sign, "Park Street = 70075, 70076".
export function stopOf(text: any): { label: string; query: string } {
  const typed = String(text ?? '').trim()
  const at = typed.indexOf('=')
  return at > 0 ? { label: typed.slice(0, at).trim(), query: typed.slice(at + 1).trim() } : { label: '', query: typed }
}

// The board kept for these stops, or null (another stop's is not shown).
export function loadBoard(app: FrameOSApp, key: string): Board | null {
  const kept = app.state.board
  return kept && typeof kept === 'object' && kept.key === key && Array.isArray(kept.stops) ? (kept as Board) : null
}

export const saveBoard = (board: Board) => frameos.setState('board', board as any)

// Whether to ask the provider now: nothing kept, the footer tapped, or the
// gap gone by.
export function due(board: Board | null, now: number): boolean {
  const force = frameos.recall('force') === true
  if (force) frameos.remember('force', null)
  return !board || force || now - (board.tried || 0) >= FETCH_GAP
}

// The departures still to come that a person at this stop can catch, of the
// lines asked for.
export function upcoming(list: Departure[], now: number, walkMinutes: number, only: string[]): Departure[] {
  const from = now + Math.max(0, walkMinutes) * MINUTE - 30 * 1000
  const wanted = only.map((name) => name.toLowerCase())
  return list.filter((d) => d.at >= from && (!wanted.length || wanted.indexOf(String(d.line).toLowerCase()) >= 0))
}

export function clockText(at: number, twelve: boolean): string {
  const d = new Date(at)
  const minutes = String(d.getMinutes()).padStart(2, '0')
  if (!twelve) return `${d.getHours()}:${minutes}`
  const hour = d.getHours() % 12 || 12
  return `${hour}:${minutes} ${d.getHours() < 12 ? 'am' : 'pm'}`
}

// "Now", "4 min", or past the hour the clock time: { big, unit }.
export function whenText(at: number, now: number, twelve: boolean): { big: string; unit: string } {
  const minutes = Math.floor((at - now) / MINUTE)
  if (minutes <= 0) return { big: 'Now', unit: '' }
  if (minutes < 60) return { big: String(minutes), unit: 'min' }
  return { big: clockText(at, twelve), unit: '' }
}

// A delay worth saying, in whole minutes: "+3", "-1", or "".
export function delayText(delay: number | null): string {
  if (delay === null || delay === undefined || !isFinite(delay)) return ''
  const minutes = Math.round(delay / 60)
  if (minutes >= 1) return `+${minutes}`
  if (minutes <= -1) return `${minutes}`
  return ''
}

// How long ago, said plainly: "just now", "4 min ago", "at 10:20".
export function agoText(at: number, now: number, twelve: boolean): string {
  const minutes = Math.floor((now - at) / MINUTE)
  if (minutes < 1) return 'just now'
  if (minutes < 60) return `${minutes} min ago`
  return `at ${clockText(at, twelve)}`
}

// A color's parts, from "DA291C" or "#da291c".
function rgb(hex: string): [number, number, number] {
  const h = String(hex || '').replace('#', '')
  return [parseInt(h.slice(0, 2), 16) || 0, parseInt(h.slice(2, 4), 16) || 0, parseInt(h.slice(4, 6), 16) || 0]
}

// How light a color looks, 0 to 255.
export function lightness(hex: string): number {
  const [r, g, b] = rgb(hex)
  return 0.299 * r + 0.587 * g + 0.114 * b
}

// Black or white, whichever reads on this color.
export function inkOn(hex: string): string {
  return lightness(hex) > 150 ? '#000000' : '#ffffff'
}

// "DA291C", "#da291c" or anything else: six hex digits in capitals, or "".
export function hex(text: any): string {
  return /^#?[0-9a-fA-F]{6}$/.test(String(text || '')) ? String(text).replace('#', '').toUpperCase() : ''
}

// Color e-paper (Spectra's six inks, as dither.nim measures them): a line's
// color as the nearest ink, so a badge is one solid ink and not a dither.
export const INKS = { red: '#6b1119', yellow: '#c7bb00', green: '#2a5531', blue: '#18539a', black: '#000000' }

export function nearestInk(color: string): string {
  const [r, g, b] = rgb(color)
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)
  if (max - min < 48) return INKS.black
  let hue = 0
  if (max === r) hue = ((g - b) / (max - min)) * 60
  else if (max === g) hue = (2 + (b - r) / (max - min)) * 60
  else hue = (4 + (r - g) / (max - min)) * 60
  if (hue < 0) hue += 360
  if (hue < 15 || hue >= 300) return INKS.red
  if (hue < 70) return INKS.yellow
  if (hue < 170) return INKS.green
  return INKS.blue
}

// "Red, 47" as a list of names.
export function namesOf(text: string): string[] {
  return String(text || '')
    .split(',')
    .map((part) => part.trim())
    .filter(Boolean)
}

sources.ui.tsx:
// The station board: each stop's name, its next departures as rows (the line
// in its color, where it goes, the minutes until it leaves), and a footer
// that says how fresh they are or what went wrong. A live prediction has the
// live mark, a timetable time is drawn quieter with a clock, a delay is a
// chip beside the time, and a canceled trip says so.
import { agoText, clockText, delayText, inkOn, INKS, lightness, MINUTE, namesOf, nearestInk, upcoming, whenText, type Board, type Departure, type Stop } from './board'

type Theme = {
  page: string
  ink: string
  muted: string
  rule: string
  badge: string
  badgeInk: string
  live: string
  late: string
  early: string
  gone: string
  chipLate: string
  chipEarly: string
  bar: string
  barError: string
  paper: boolean
  high: boolean
}

const DARK: Theme = {
  page: '#0f172a', ink: '#f8fafc', muted: '#94a3b8', rule: '#1e293b', badge: '#334155', badgeInk: '#ffffff',
  live: '#34d399', late: '#fbbf24', early: '#38bdf8', gone: '#fb7185',
  chipLate: 'bg-[#fbbf24] text-[#111827]', chipEarly: 'bg-[#38bdf8] text-[#111827]',
  bar: 'text-[#94a3b8]', barError: 'bg-[#7f1d1d] text-[#fee2e2]', paper: false, high: false,
}
const LIGHT: Theme = {
  page: '#f8fafc', ink: '#0f172a', muted: '#64748b', rule: '#e2e8f0', badge: '#cbd5e1', badgeInk: '#0f172a',
  live: '#059669', late: '#d97706', early: '#0284c7', gone: '#e11d48',
  chipLate: 'bg-[#f59e0b] text-[#111827]', chipEarly: 'bg-[#0ea5e9] text-white',
  bar: 'text-[#64748b]', barError: 'bg-[#fee2e2] text-[#7f1d1d]', paper: false, high: false,
}
// No color on the panel (black and white, greys): black on white, every
// badge black, a delay an inverted chip.
const HIGH: Theme = {
  page: '#ffffff', ink: '#000000', muted: '#000000', rule: '#000000', badge: '#000000', badgeInk: '#ffffff',
  live: '#000000', late: '#000000', early: '#000000', gone: '#000000',
  chipLate: 'bg-black text-white', chipEarly: 'bg-white text-black border-2 border-black',
  bar: 'text-black', barError: 'bg-black text-white', paper: true, high: true,
}
// Color e-paper: the same page with the lines, the live mark and the chips in
// solid inks.
const INK: Theme = {
  ...HIGH,
  live: INKS.green, late: INKS.red, early: INKS.blue, gone: INKS.red,
  chipLate: `bg-[${INKS.red}] text-white`, chipEarly: `bg-[${INKS.blue}] text-white`,
  barError: `bg-[${INKS.red}] text-white`, high: false,
}

function themeOf(app: FrameOSApp): Theme {
  const mode = app.state.contrast || 'auto'
  if (mode === 'high' || (mode === 'auto' && app.frame.color === false)) return HIGH
  if (mode === 'auto' && app.frame.paper === true) return INK
  return app.state.look === 'light' ? LIGHT : DARK
}

// A line's badge colors on this panel, and a ring around one that would
// vanish into the page (a black line on the dark board).
function badgeOf(t: Theme, d: Departure): { back: string; ink: string; ring: string } {
  if (t.high) return { back: t.badge, ink: t.badgeInk, ring: '' }
  if (!d.color) return { back: t.paper ? INKS.black : t.badge, ink: t.paper ? '#ffffff' : t.badgeInk, ring: '' }
  if (t.paper) {
    const back = nearestInk(d.color)
    return { back, ink: back === INKS.yellow ? '#000000' : '#ffffff', ring: '' }
  }
  const near = Math.abs(lightness(d.color) - lightness(t.page.slice(1))) < 40
  return { back: `#${d.color}`, ink: d.text ? `#${d.text}` : inkOn(d.color), ring: near ? `border-2 border-[${t.muted}]` : '' }
}

// Sizes are for a panel about 480 px on its shorter side; a big one (the
// 13.3" e-paper, 1200 px) draws them K times larger, by halves.
let K = 1
const px = (n: number) => Math.round(n * K)

type Sizes = { small: boolean; name: number; clock: number; dest: number; badge: number; badgeH: number; time: number; unit: number; foot: number; row: number; pad: number; gap: number; timeW: number; where: boolean }

function sizesFor(small: boolean, narrow: boolean): Sizes {
  if (small) return { small, name: 20, clock: 20, dest: 16, badge: 14, badgeH: 24, time: 18, unit: 12, foot: 11, row: 36, pad: 10, gap: 8, timeW: 62, where: false }
  return { small, name: 30, clock: 30, dest: narrow ? 21 : 24, badge: narrow ? 18 : 20, badgeH: narrow ? 32 : 36, time: narrow ? 24 : 28, unit: narrow ? 14 : 16, foot: 15, row: narrow ? 48 : 54, pad: 20, gap: 12, timeW: narrow ? 92 : 108, where: !narrow }
}

const LiveMark = ({ color, size }: { color: string; size: number }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2.6} strokeLinecap="round">
    <circle cx="12" cy="17" r="2.2" fill={color} stroke="none" />
    <path d="M7.5 12.5a6.4 6.4 0 0 1 9 0" />
    <path d="M4 9a11.3 11.3 0 0 1 16 0" />
  </svg>
)

const ClockMark = ({ color, size }: { color: string; size: number }) => (
  <svg className={`w-[${size}px] h-[${size}px]`} viewBox="0 0 24 24" fill="none" stroke={color} strokeWidth={2.4} strokeLinecap="round" strokeLinejoin="round">
    <circle cx="12" cy="12" r="8.5" />
    <path d="M12 7.5V12l3 2" />
  </svg>
)

function Row({ d, t, z, now, twelve, badgeW, rowH, last }: { d: Departure; t: Theme; z: Sizes; now: number; twelve: boolean; badgeW: number; rowH: number; last: boolean }) {
  const badge = badgeOf(t, d)
  const when = whenText(d.at, now, twelve)
  const late = delayText(d.delay)
  // Too narrow for a chip (a 2.8" screen): the time itself in the delay's color.
  const chip = late && !d.gone && !z.small
  const timeColor = d.gone ? t.gone : late && z.small && !t.high ? (late[0] === '+' ? t.late : t.early) : d.live ? t.ink : t.muted
  const rule = last ? '' : t.high ? 'border-b-2 border-black' : `border-b border-[${t.rule}]`
  return (
    <div className={`flex items-center gap-[${px(z.gap)}px] h-[${rowH}px] ${rule}`}>
      <div className={`shrink-0 flex items-center justify-center w-[${badgeW}px] h-[${px(z.badgeH)}px] rounded-[${px(z.badgeH / 4)}px] bg-[${badge.back}] ${badge.ring} text-[${badge.ink}] text-[${px(z.badge)}px] font-bold`}>
        <span className="truncate">{d.line || '?'}</span>
      </div>
      <span className={`flex-1 min-w-0 truncate text-[${px(z.dest)}px] ${d.gone ? `text-[${t.muted}]` : ''}`}>{d.to || d.line}</span>
      {z.where && d.where ? <span className={`shrink-0 text-[${px(z.unit)}px] text-[${t.muted}]`}>{d.where}</span> : null}
      {chip ? (
        <span className={`shrink-0 px-[${px(6)}px] rounded-[${px(6)}px] text-[${px(z.unit)}px] font-bold ${late[0] === '+' ? t.chipLate : t.chipEarly}`}>{late}</span>
      ) : null}
      <div className={`shrink-0 w-[${px(z.timeW)}px] flex items-center justify-end gap-[${px(4)}px] text-[${timeColor}]`}>
        {d.gone ? (
          <span className={`text-[${px(z.unit + 2)}px] font-bold`}>Canceled</span>
        ) : (
          <>
            {d.live ? <LiveMark color={t.live} size={px(z.unit)} /> : <ClockMark color={t.muted} size={px(z.unit)} />}
            <span className={`${when.unit || when.big === 'Now' ? `text-[${px(z.time)}px]` : `text-[${px(z.time - 4)}px]`} ${d.live ? 'font-bold' : ''}`}>{when.big}</span>
            {when.unit ? <span className={`text-[${px(z.unit)}px]`}>{when.unit}</span> : null}
          </>
        )}
      </div>
    </div>
  )
}

// One stop: its name (and the clock beside it, if given), and as many rows
// as fit in `height`, sharing what is left over.
function Section({ stop, t, z, now, twelve, clock, height, width, center = false }: { stop: Stop; t: Theme; z: Sizes; now: number; twelve: boolean; clock: string; height: number; width: number; center?: boolean }) {
  const headH = px(z.name * 1.5)
  const rows = Math.max(1, Math.floor((height - headH) / px(z.row)))
  const rowH = Math.min(Math.floor((height - headH) / rows), px(z.row * 1.25))
  const shown = stop.list.slice(0, rows)
  // Every badge of the section as wide as its longest name needs, within reason.
  const longest = shown.reduce((n, d) => Math.max(n, String(d.line || '?').length), 1)
  const badgeW = Math.min(Math.round(width * 0.24), px(z.badge * (0.66 * Math.min(longest, 6) + 1.2)))
  return (
    <div className={`flex flex-col w-[${width}px] h-[${height}px]`}>
      <div className={`flex items-center ${center ? 'justify-center' : ''} h-[${headH}px] gap-[${px(z.gap)}px]`}>
        <span className={`${center ? 'text-center' : 'flex-1'} min-w-0 truncate text-[${px(z.name)}px] font-bold`}>{stop.name}</span>
        {clock ? <span className={`shrink-0 text-[${px(z.clock)}px] text-[${t.muted}]`}>{clock}</span> : null}
      </div>
      {shown.length ? (
        shown.map((d, i) => <Row d={d} t={t} z={z} now={now} twelve={twelve} badgeW={badgeW} rowH={rowH} last={i === shown.length - 1} />)
      ) : (
        <span className={`text-[${px(z.dest)}px] text-[${t.muted}] pt-[${px(z.gap)}px]`}>No departures coming up</span>
      )}
    </div>
  )
}

// The line at the bottom: what the marks on the board mean and how fresh it
// is, or what went wrong. A tap on it asks again.
function Footer({ board, t, z, now, twelve, provider, width, compact, marks, center = false }: { board: View['board']; t: Theme; z: Sizes; now: number; twelve: boolean; provider: string; width: number; compact: boolean; marks: { live: boolean; timetable: boolean }; center?: boolean }) {
  const ask = () => frameos.remember('force', true)
  const h = px(z.foot * 1.8)
  if (board?.error) {
    const kept = board.at > 0 ? (compact ? ` (from ${clockText(board.at, twelve)})` : ` Showing departures from ${clockText(board.at, twelve)}.`) : ''
    return (
      <div className={`flex items-center w-[${width}px] min-h-[${h}px] px-[${px(8)}px] rounded-[${px(6)}px] ${t.barError} text-[${px(z.foot)}px]`} onClick={ask}>
        <span className="line-clamp-2">{`${provider}: ${board.error}.${kept}`}</span>
      </div>
    )
  }
  const fresh = board?.loading ? 'Updating…' : board?.at ? `Updated ${agoText(board.at, now, twelve)}` : ''
  const feedOld = board?.feedTime && now - board.feedTime > 10 * MINUTE ? ` · feed ${agoText(board.feedTime, now, twelve)}` : ''
  return (
    <div className={`flex items-center w-[${width}px] h-[${h}px] gap-[${px(6)}px] text-[${px(z.foot)}px] ${t.bar}`} onClick={ask}>
      {compact || !marks.live ? null : <LiveMark color={t.live} size={px(z.foot)} />}
      {compact || !marks.live ? null : <span className={`pr-[${px(8)}px]`}>Live</span>}
      {compact || !marks.timetable ? null : <ClockMark color={t.muted} size={px(z.foot)} />}
      {compact || !marks.timetable ? null : <span>Timetable</span>}
      {/* A spring and the words: a truncated text-right span drew nothing on 2026.11.14. */}
      <div className={center ? '' : 'flex-1'} />
      <span className={`min-w-0 truncate ${center ? 'flex-1 text-center' : ''}`}>{`${fresh}${feedOld}`}</span>
    </div>
  )
}

const sizeOf = (app: FrameOSApp, context: FrameOSContext) => ({
  W: context?.imageWidth ?? app.frame.width,
  H: context?.imageHeight ?? app.frame.height,
  round: context?.round === true,
})

// A card in the middle: what to set, or what went wrong before anything came.
export function setupCard(app: FrameOSApp, context: FrameOSContext, title: string, text: string) {
  const { W, H, round } = sizeOf(app, context)
  const t = themeOf(app)
  K = !round && Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1
  const side = round ? Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2) : W
  return (
    <div className={`flex items-center justify-center w-[${W}px] h-[${H}px] bg-[${t.page}] text-[${t.ink}]`}>
      <div className={`flex flex-col items-center gap-[${px(12)}px] w-[${side}px] p-[${px(24)}px] text-center`}>
        <span className={`text-[${px(28)}px] font-bold`}>{title}</span>
        <span className={`text-[${px(18)}px] text-[${t.muted}]`}>{text}</span>
      </div>
    </div>
  )
}

export type View = {
  // The provider's name, for the footer and errors.
  provider: string
  // The scene's own name, for the card shown before anything came.
  title: string
  // Each stop's name of the person's own (or ''), and what was asked for.
  labels: string[]
  queries: string[]
  board: (Board & { loading?: boolean }) | null
}

export function drawBoard(app: FrameOSApp, context: FrameOSContext, view: View) {
  const { W, H, round } = sizeOf(app, context)
  const t = themeOf(app)
  const twelve = app.state.clock === '12'
  const now = Date.now()
  const walk = Math.max(0, Math.min(120, Number(app.state.walk) || 0))
  const only = namesOf(app.state.only)
  const board = view.board
  K = !round && Math.min(W, H) >= 900 ? Math.min(3, Math.floor((Math.min(W, H) / 480) * 2) / 2) : 1

  // The departures still to catch: a list fetched a while ago counts down
  // from the clock and loses the ones gone.
  const stops: Stop[] = (board?.stops || []).map((s, i) => ({
    name: view.labels[i] || s.name || view.queries[i] || '',
    list: upcoming(s.list || [], now, walk, only),
  }))
  const clock = clockText(now, twelve)
  // Which marks the board has to explain (TfL's are all live).
  const all = stops.flatMap((s) => s.list).filter((d) => !d.gone)
  const marks = { live: all.some((d) => d.live), timetable: all.some((d) => !d.live) }

  if (!stops.length) {
    return setupCard(app, context, view.title, board?.error ? `${view.provider}: ${board.error}.` : `Loading departures from ${view.provider}…`)
  }

  if (round) {
    // One list in the circle: every stop's departures by time, the names and
    // the clock in the arc above, the freshness below.
    const R = Math.min(W, H) / 2 - 12
    const z = sizesFor(R < 200, true)
    const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
    const top = Math.round(R * 0.62)
    const bottom = Math.round(R * 0.6)
    const listW = Math.min(chord(top), chord(bottom))
    const merged: Stop = { name: stops.map((s) => s.name).join(' · '), list: stops.flatMap((s) => s.list).sort((a, b) => a.at - b.at) }
    const footW = chord(R * 0.78)
    return (
      <div className={`relative w-[${W}px] h-[${H}px] bg-[${t.page}] text-[${t.ink}]`}>
        <div className={`absolute left-[${Math.round(W / 2 - chord(R * 0.86) / 2)}px] top-[${Math.round(H / 2 - R * 0.86)}px] w-[${chord(R * 0.86)}px] flex flex-col items-center`}>
          <span className={`text-[${px(z.clock)}px] text-[${t.muted}]`}>{clock}</span>
        </div>
        <div className={`absolute left-[${Math.round(W / 2 - listW / 2)}px] top-[${Math.round(H / 2 - top)}px]`}>
          <Section stop={merged} t={t} z={z} now={now} twelve={twelve} clock="" height={top + bottom} width={listW} center />
        </div>
        <div className={`absolute left-[${Math.round(W / 2 - footW / 2)}px] top-[${Math.round(H / 2 + R * 0.66)}px]`}>
          <Footer board={board} t={t} z={z} now={now} twelve={twelve} provider={view.provider} width={footW} marks={marks} compact center />
        </div>
      </div>
    )
  }

  const small = Math.min(W, H) < 330
  const wide = W >= H * 1.3 && W >= 640
  const columns = stops.length > 1 && wide
  const z = sizesFor(small, columns || W < 520)
  const pad = px(z.pad)
  const gap = px(z.gap * 2)
  const footH = px(z.foot * 1.8) + (board?.error ? px(z.foot * 1.3) : 0)
  const innerW = W - pad * 2
  const bodyH = H - pad * 2 - footH - px(z.gap)
  const colW = columns ? Math.floor((innerW - gap) / 2) : innerW
  const sections = columns
    ? stops.map((s, i) => ({ s, h: bodyH, clock: i === stops.length - 1 ? clock : '' }))
    : stops.map((s, i) => ({ s, h: stops.length > 1 ? Math.floor((bodyH - gap) / 2) : bodyH, clock: i === 0 ? clock : '' }))
  return (
    <div className={`flex flex-col w-[${W}px] h-[${H}px] p-[${pad}px] gap-[${px(z.gap)}px] bg-[${t.page}] text-[${t.ink}]`}>
      <div className={`flex ${columns ? 'flex-row' : 'flex-col'} gap-[${gap}px] h-[${bodyH}px]`}>
        {sections.map(({ s, h, clock: shown }) => (
          <Section stop={s} t={t} z={z} now={now} twelve={twelve} clock={shown} height={h} width={colW} />
        ))}
      </div>
      <Footer board={board} t={t} z={z} now={now} twelve={twelve} provider={view.provider} width={innerW} marks={marks} compact={small} />
    </div>
  )
}

