// Asking an agency's JSON API: one small answer a stop, within the render.
import { saveBoard, type Board, type Stop } from './board'

// A request that answers JSON, or throws with what went wrong.
export function getJson(url: string, options: Record<string, any> = {}): any {
  const reply = frameos.httpRequest(url, { timeoutMs: 20000, ...options })
  if (!reply || reply.error) throw new Error(reply?.error || 'no answer')
  if (reply.status === 429) throw new Error('too many requests (HTTP 429): try a longer refresh interval')
  if (reply.status < 200 || reply.status >= 300) throw new Error(`HTTP ${reply.status}`)
  try {
    return JSON.parse(reply.body || 'null')
  } catch (e) {
    throw new Error('the answer was not JSON')
  }
}

export const when = (text: any): number => (text ? Date.parse(String(text)) : NaN)

// Every stop asked again. What goes wrong is kept with the last good
// departures, which still show. `names` is the board's own lookup of stop
// names to ids (Entur's), kept with it.
export function refreshStops(
  key: string,
  kept: Board | null,
  now: number,
  queries: string[],
  read: (query: string, names: Record<string, { id: string; name: string }>) => Stop,
): Board {
  const base: Board = kept || { key, at: 0, tried: 0, stops: [], error: '' }
  let board: Board
  try {
    const names = { ...(base.names || {}) }
    const stops = queries.map((query) => read(query, names))
    board = { key, at: now, tried: now, error: '', names, stops: stops.map((s) => ({ name: s.name, list: s.list.slice(0, 24) })) }
  } catch (e) {
    board = { ...base, key, tried: now, error: String((e as any)?.message || e) }
  }
  saveBoard(board)
  return board
}

