// Transport for London's API (api.tfl.gov.uk): the arrivals at one stop
// point, by its id (940GZZLUKSX is King's Cross St. Pancras on the
// Underground, 490000129R a bus stop). No key needed. Every arrival is a
// prediction: TfL publishes no timetable here.
import type { Departure, Stop } from './board'
import { getJson, when } from './json'

// TfL's lines: the code on the badge, its color and the words' color.
const LINES: Record<string, [string, string, string]> = {
  bakerloo: ['BAK', 'B36305', 'FFFFFF'],
  central: ['CEN', 'E32017', 'FFFFFF'],
  circle: ['CIR', 'FFD300', '00205B'],
  district: ['DIS', '00782A', 'FFFFFF'],
  'hammersmith-city': ['H&C', 'F3A9BB', '00205B'],
  jubilee: ['JUB', 'A0A5A9', 'FFFFFF'],
  metropolitan: ['MET', '9B0056', 'FFFFFF'],
  northern: ['NOR', '000000', 'FFFFFF'],
  piccadilly: ['PIC', '003688', 'FFFFFF'],
  victoria: ['VIC', '0098D4', 'FFFFFF'],
  'waterloo-city': ['W&C', '95CDBA', '00205B'],
  elizabeth: ['ELZ', '6950A1', 'FFFFFF'],
  dlr: ['DLR', '00A4A7', 'FFFFFF'],
  liberty: ['LIB', '5D6061', 'FFFFFF'],
  lioness: ['LIO', 'FAA61A', '00205B'],
  mildmay: ['MIL', '0077AD', 'FFFFFF'],
  suffragette: ['SUF', '5BBD72', 'FFFFFF'],
  weaver: ['WEA', '823A62', 'FFFFFF'],
  windrush: ['WIN', 'ED1B00', 'FFFFFF'],
}

const place = (text: any) =>
  String(text || '')
    .replace(/ (Underground|DLR|Rail|Overground|Elizabeth Line) Station$/i, '')
    .replace(/ Station$/i, '')
    .replace(/ \(London\)$/i, '')
    .trim()

export function tfl(stop: string, now: number): Stop {
  const id = stop.trim()
  const arrivals = getJson(`https://api.tfl.gov.uk/StopPoint/${encodeURIComponent(id)}/Arrivals`)
  if (!Array.isArray(arrivals)) throw new Error('TfL did not answer with arrivals')
  let name = ''
  const list: Departure[] = []
  for (const a of arrivals) {
    const at = when(a.expectedArrival)
    if (!(at > 0)) continue
    if (!name && a.stationName) name = place(a.stationName)
    const known = LINES[String(a.lineId || '')]
    const bus = a.modeName === 'bus'
    const platform = String(a.platformName || '')
    list.push({
      line: known ? known[0] : String(a.lineName || ''),
      color: known ? known[1] : bus ? 'E1251B' : '',
      text: known ? known[2] : 'FFFFFF',
      to: place(a.destinationName) || String(a.towards || ''),
      at,
      live: true,
      delay: null,
      gone: false,
      where: /unknown|null/i.test(platform) || !platform ? '' : bus ? `Stop ${platform}` : platform.split(' - ').pop() || '',
    })
  }
  list.sort((x, y) => x.at - y.at)
  return { name: name || id, list: list.slice(0, 30) }
}

