import { get } from './app'
import { delayText, INKS, nearestInk, upcoming, whenText } from './board'
import { tfl } from './tfl'

// Saturday 28 November 2026, 15:00 in London.
const NOW = Date.UTC(2026, 10, 28, 15, 0, 0)
const MIN = 60 * 1000

function at<T>(when: number, run: () => T): T {
  const real = Date.now
  Date.now = () => when
  try {
    return run()
  } finally {
    Date.now = real
  }
}

// Every string in a JSX tree, to see what a render says.
function textOf(node: any): string {
  if (node === null || node === undefined || node === false || node === true) return ''
  if (typeof node === 'string' || typeof node === 'number') return String(node)
  if (Array.isArray(node)) return node.map(textOf).join(' ')
  if (typeof node.type === 'function') return textOf(node.type(node.props || {}))
  return textOf(node.props?.children)
}

// TfL's arrivals, shaped as api.tfl.gov.uk sends them (in no order).
const arrival = (lineId: string, lineName: string, mode: string, destination: string, platform: string, minutes: number, station: string) => ({
  $type: 'Tfl.Api.Presentation.Entities.Prediction, Tfl.Api.Presentation.Entities',
  lineId, lineName, modeName: mode, destinationName: destination, towards: '', platformName: platform,
  expectedArrival: new Date(NOW + minutes * MIN).toISOString().replace('.000', ''), timeToStation: minutes * 60, stationName: station,
})
const KINGS_CROSS = "King's Cross St. Pancras Underground Station"
const ARRIVALS = [
  arrival('northern', 'Northern', 'tube', 'Morden Underground Station', 'Southbound - Platform 8', 6, KINGS_CROSS),
  arrival('victoria', 'Victoria', 'tube', 'Brixton Underground Station', 'Southbound - Platform 4', 2, KINGS_CROSS),
  arrival('piccadilly', 'Piccadilly', 'tube', 'Heathrow Terminal 5 Underground Station', 'Westbound - Platform 5', 3.5, KINGS_CROSS),
  arrival('hammersmith-city', 'Hammersmith & City', 'tube', 'Hammersmith (H&C Line) Underground Station', 'Platform Unknown', 9, KINGS_CROSS),
]

describe('TfL', () => {
  it('reads the arrivals, in order, with the lines in their colors', () => {
    const http = mock.httpRequest(() => mock.json(ARRIVALS))
    const stop = tfl('940GZZLUKSX', NOW)
    expect(String(http.calls[0][0])).toBe('https://api.tfl.gov.uk/StopPoint/940GZZLUKSX/Arrivals')
    expect(stop.name).toBe("King's Cross St. Pancras")
    expect(stop.list.map((d) => [d.line, d.color, d.text, d.to, d.where, (d.at - NOW) / MIN, d.live])).toEqual([
      ['VIC', '0098D4', 'FFFFFF', 'Brixton', 'Platform 4', 2, true],
      ['PIC', '003688', 'FFFFFF', 'Heathrow Terminal 5', 'Platform 5', 3.5, true],
      ['NOR', '000000', 'FFFFFF', 'Morden', 'Platform 8', 6, true],
      ['H&C', 'F3A9BB', '00205B', 'Hammersmith (H&C Line)', '', 9, true],
    ])
  })

  it('reads a bus stop', () => {
    mock.httpRequest(() =>
      mock.json([
        { lineId: '73', lineName: '73', modeName: 'bus', destinationName: 'Oxford Circus', platformName: 'R', expectedArrival: '2026-11-28T15:07:30Z', stationName: "King's Cross Station" },
        { lineId: '390', lineName: '390', modeName: 'bus', destinationName: '', towards: 'Victoria', platformName: 'R', expectedArrival: '2026-11-28T15:04:00Z', stationName: "King's Cross Station" },
      ]),
    )
    const stop = tfl('490000129R', NOW)
    expect(stop.name).toBe("King's Cross")
    expect(stop.list.map((d) => [d.line, d.color, d.to, d.where, (d.at - NOW) / MIN])).toEqual([
      ['390', 'E1251B', 'Victoria', 'Stop R', 4],
      ['73', 'E1251B', 'Oxford Circus', 'Stop R', 7.5],
    ])
  })

  it('says what went wrong', () => {
    mock.httpRequest(() => mock.json({ message: 'The following stop point is not recognised: 940GZZLUXXX' }, 404))
    expect(() => tfl('940GZZLUXXX', NOW)).toThrow('HTTP 404')
    mock.httpRequest(() => mock.json({ message: 'nope' }))
    expect(() => tfl('940GZZLUKSX', NOW)).toThrow('TfL did not answer with arrivals')
  })
})

const departure = (minutes: number) => ({ line: 'VIC', color: '0098D4', text: 'FFFFFF', to: 'Brixton', at: NOW + minutes * MIN, live: true, delay: null, gone: false, where: '' })

describe('the scene', () => {
  it('keeps the last good arrivals when TfL fails, and says so', () => {
    mock.httpRequest(() => mock.response(429, 'slow down'))
    const kept = { key: '940GZZLUKSX', at: NOW - 5 * MIN, tried: NOW - 5 * MIN, error: '', stops: [{ name: "King's Cross St. Pancras", list: [departure(-1), departure(3), departure(9)] }] }
    const app = makeApp({ state: { stop: '940GZZLUKSX', board: kept } })
    const tree = at(NOW, () => get(app, makeContext()))
    expect(app.state.board.error).toBe('too many requests (HTTP 429): try a longer refresh interval')
    const said = textOf(tree)
    expect(said).toContain('TfL: too many requests (HTTP 429)')
    expect(said.split('Brixton').length - 1).toBe(2)
  })

  it('asks again only after the gap, unless the footer is tapped, and shows two stops', () => {
    const http = mock.httpRequest(() => mock.json(ARRIVALS))
    const app = makeApp({ state: { stop: '940GZZLUKSX', stop2: 'Bus = 490000129R' } })
    const tree = at(NOW, () => get(app, makeContext()))
    expect(http.calls.length).toBe(2)
    at(NOW + 10 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(2)
    frameos.remember('force', true)
    at(NOW + 12 * 1000, () => get(app, makeContext()))
    expect(http.calls.length).toBe(4)
    const said = textOf(tree)
    expect(said).toContain("King's Cross St. Pancras")
    expect(said).toContain('Bus')
  })

  it('asks for a stop', () => {
    expect(textOf(get(makeApp({ state: { stop: '' } }), makeContext()))).toContain('its TfL StopPoint id')
  })
})

describe('the board', () => {
  it('counts down, and says delays and lines as each panel shows them', () => {
    expect(whenText(NOW + 20 * 1000, NOW, false)).toEqual({ big: 'Now', unit: '' })
    expect(whenText(NOW + 4.9 * MIN, NOW, false)).toEqual({ big: '4', unit: 'min' })
    expect(whenText(NOW + 75 * MIN, NOW, true).big).toMatch(/^\d{1,2}:\d\d (am|pm)$/)
    expect([delayText(130), delayText(-61), delayText(20), delayText(null)]).toEqual(['+2', '-1', '', ''])
    expect([nearestInk('E32017'), nearestInk('FFD300'), nearestInk('00782A'), nearestInk('003688'), nearestInk('A0A5A9')]).toEqual([
      INKS.red, INKS.yellow, INKS.green, INKS.blue, INKS.black,
    ])
  })

  it('leaves out what is gone, what cannot be caught on foot, and other lines', () => {
    const list = [-2, 3, 8, 15].map((m, i) => ({ ...departure(m), line: i % 2 ? '73' : 'VIC' }))
    expect(upcoming(list, NOW, 0, []).map((d) => (d.at - NOW) / MIN)).toEqual([3, 8, 15])
    expect(upcoming(list, NOW, 5, []).map((d) => (d.at - NOW) / MIN)).toEqual([8, 15])
    expect(upcoming(list, NOW, 0, ['vic']).map((d) => (d.at - NOW) / MIN)).toEqual([8])
  })
})
